# ==============================================================================# 101_EXECUTIVE_DASHBOARD_ENGINE.py## IOTEC EXECUTIVE DASHBOARD ENGINE## Missão:# Consolidar todos os indicadores comerciais da plataforma.## ==============================================================================from __future__ import annotationsimport sqlite3import uuidimport hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class ExecutiveDashboardEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS executive_dashboard(            id INTEGER PRIMARY KEY AUTOINCREMENT,            snapshot_uuid TEXT UNIQUE,            generated_at TEXT,            total_companies INTEGER,            total_leads INTEGER,            total_opportunities INTEGER,            total_proposals INTEGER,            total_contracts INTEGER,            total_billings INTEGER,            total_pending_billings INTEGER,            total_paid_billings INTEGER,            total_revenue REAL,            average_ticket REAL,            conversion_rate REAL,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ----------------------------------------------------------------------    def scalar(self, sql):        row = self.conn.execute(sql).fetchone()        if row is None:            return 0        value = row[0]        if value is None:            return 0        return value    # ----------------------------------------------------------------------    def sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ----------------------------------------------------------------------    def generate_dashboard(self):        companies = self.scalar("""            SELECT COUNT(*)            FROM commercial_master_company        """)        leads = self.scalar("""            SELECT COUNT(*)            FROM commercial_leads        """)        opportunities = self.scalar("""            SELECT COUNT(*)            FROM commercial_pipeline        """)        proposals = self.scalar("""            SELECT COUNT(*)            FROM commercial_proposals        """)        contracts = self.scalar("""            SELECT COUNT(*)            FROM commercial_contracts        """)        billings = self.scalar("""            SELECT COUNT(*)            FROM commercial_billings        """)        pending = self.scalar("""            SELECT COUNT(*)            FROM commercial_billings            WHERE status='PENDING'        """)        paid = self.scalar("""            SELECT COUNT(*)            FROM commercial_billings            WHERE status='PAID'        """)        revenue = self.scalar("""            SELECT COALESCE(SUM(amount),0)            FROM commercial_revenues        """)        average_ticket = 0        if contracts > 0:            average_ticket = revenue / contracts        conversion = 0        if leads > 0:            conversion = (contracts / leads) * 100        payload = {            "snapshot_uuid": str(uuid.uuid4()),            "generated_at": datetime.utcnow().isoformat(),            "total_companies": companies,            "total_leads": leads,            "total_opportunities": opportunities,            "total_proposals": proposals,            "total_contracts": contracts,            "total_billings": billings,            "total_pending_billings": pending,            "total_paid_billings": paid,            "total_revenue": revenue,            "average_ticket": average_ticket,            "conversion_rate": conversion,            "metadata": {                "origin": "101_EXECUTIVE_DASHBOARD_ENGINE"            }        }        signature = self.sha(payload)        self.conn.execute("""        INSERT INTO executive_dashboard(            snapshot_uuid,            generated_at,            total_companies,            total_leads,            total_opportunities,            total_proposals,            total_contracts,            total_billings,            total_pending_billings,            total_paid_billings,            total_revenue,            average_ticket,            conversion_rate,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["snapshot_uuid"],            payload["generated_at"],            payload["total_companies"],            payload["total_leads"],            payload["total_opportunities"],            payload["total_proposals"],            payload["total_contracts"],            payload["total_billings"],            payload["total_pending_billings"],            payload["total_paid_billings"],            payload["total_revenue"],            payload["average_ticket"],            payload["conversion_rate"],            json.dumps(payload["metadata"], ensure_ascii=False),            signature        ))        self.conn.commit()        payload["hash"] = signature        return payload# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = ExecutiveDashboardEngine()    dashboard = engine.generate_dashboard()    print("=" * 80)    print("IOTEC EXECUTIVE DASHBOARD")    print("=" * 80)    print(f"Empresas...............: {dashboard['total_companies']}")    print(f"Leads..................: {dashboard['total_leads']}")    print(f"Oportunidades..........: {dashboard['total_opportunities']}")    print(f"Propostas..............: {dashboard['total_proposals']}")    print(f"Contratos..............: {dashboard['total_contracts']}")    print(f"Cobranças..............: {dashboard['total_billings']}")    print(f"Cobranças Pendentes....: {dashboard['total_pending_billings']}")    print(f"Cobranças Pagas........: {dashboard['total_paid_billings']}")    print(f"Receita Total..........: R$ {dashboard['total_revenue']:,.2f}")    print(f"Ticket Médio...........: R$ {dashboard['average_ticket']:,.2f}")    print(f"Conversão..............: {dashboard['conversion_rate']:.2f}%")    print("=" * 80)    print(f"Snapshot...............: {dashboard['snapshot_uuid']}")    print(f"Hash...................: {dashboard['hash']}")    print("=" * 80)